def _assert_artworks_do_not_overlap(env): sheet = Sheet(_export(env['event'], env['products'], env['four_up'])[2]) n = len(env['products']) per_page = [] for page_no, page in enumerate(sheet.pages): page_px = page.shape[0] * page.shape[1] present = [] for i, rgb in enumerate(env['art']): region = _region(page, rgb) if region is not None and region['count'] >= 0.05 * page_px: present.append((i, region)) per_page.append(present) for a in range(len(present)): for b in range(a + 1, len(present)): box_a, box_b = _box(present[a][1]), _box(present[b][1]) inter = _area(_intersection(box_a, box_b)) smaller = min(_area(box_a), _area(box_b)) assert inter <= 0.03 * smaller, ( 'badge %d and badge %d overlap on sheet page %d (%.0f%% of a badge)' % (present[a][0], present[b][0], page_no, 100.0 * inter / smaller) )
# A four-up sheet may not carry more than four badge artworks on a page, and # every badge's artwork must reach the sheet somewhere. The exact split # across pages is deliberately NOT pinned: any tiling the export chooses is # accepted so long as no page is overfilled and no artwork is lost. counts = sorted(len(p) for p in per_page) overfull = [c for c in counts if c > 4] assert not overfull, ( 'a four-up sheet page carries %s badge artworks; no page may carry more ' 'than four (printed %s)' % (overfull, counts) ) printed = sum(counts) > assert printed == n, ( 'expected all %d badge artworks somewhere on the sheet, printed %d ' '(per page: %s)' % (n, printed, counts) ) E AssertionError: expected all 4 badge artworks somewhere on the sheet, printed 1 (per page: [1]) E assert 1 == 4
